fields.InputDefinition:
{
  "goal": "Do the shared setup ONCE: open the application switcher dropdown next to the logo and switch to the 'Scheduling' application, then open its 'Jobs' left-nav section (scheduled jobs render as CARDS, each with a status chip, Type/Schedule/Last-Run/Next-Run meta and a Success Rate bar). Then walk these sections IN ORDER, and as you arrive at each one set \"checkpointReached\" to the exact checkpoint name shown: (1) jobs-search — type a query into the 'Search jobs...' box and confirm the card grid narrows to matches OR shows a 'No jobs found' state, then clear the search and confirm the fuller list returns; (2) jobs-status-filter — open the filter popover (funnel/'Filters' control), confirm a 'Status' dropdown (Active, Paused, Disabled, Pending, Expired) and a 'Type' dropdown render, pick a Status value and confirm the card grid narrows to matches OR shows a no-results state with an active-filter indicator/count; (3) create-job-slideout — click 'New Job' (plus icon) and confirm a slide-in editor opens with a General section (Name, Job Type, Status) and a Schedule section with a 'Cron Expression' text field, a Timezone dropdown and a Concurrency dropdown (do NOT create a job); (4) create-job-validation — with the required fields (Name, Job Type, Cron Expression — red asterisks) blank confirm the 'Create' button is DISABLED, then fill ALL three required fields — type a Name, pick a Job Type from its dropdown, and enter a cron such as '0 0 * * * *' — and confirm 'Create' becomes ENABLED only once all three are set (it stays disabled with just a Name) (do NOT finish creating); close/cancel the create editor; (5) edit-job-slideout — click an existing job CARD body and confirm a slide-in editor opens pre-populated with that job's values (Name, Job Type, Cron Expression, Timezone, Concurrency) in EDIT mode with a footer showing both 'Save' and 'Delete' (and a Statistics section if the job has runs), OR — if no jobs exist — the 'Create your first scheduled job' empty state; close/cancel; (6) pause-resume-toggle — on a job card footer click the 'Pause' or 'Resume' button and confirm the job's status chip flips (Active<->Paused) and the button relabels accordingly (a real state round-trip), OR the empty state if no jobs exist; (7) delete-confirmation — on a job card footer click the red 'Delete' (trash) button and confirm an inline confirmation overlay ('Delete this scheduled job?') with 'Delete' and 'Cancel' buttons appears, then click 'Cancel' and confirm the overlay dismisses and the card remains (do NOT confirm deletion), OR the empty state if no jobs exist. Keep going until every section has been visited. Pages can take 10-30s to load in this resource-constrained environment — wait for content rather than navigating away.",
  "startUrl": "http://localhost:4200/app/scheduling",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}

fields.ExpectedOutcomes:
{
  "goalCompleted": true,
  "finalUrlPattern": "^http://localhost:4200",
  "minConfidence": 0.7,
  "maxSteps": 90,
  "checkpoints": [
    {
      "name": "jobs-search",
      "instruction": "Jobs card grid responds to search",
      "assertions": [
        {
          "kind": "url",
          "urlPattern": "/app/scheduling"
        }
      ],
      "visualCriteria": [
        "The Jobs section renders scheduled jobs as cards (status chip + Schedule/Success-Rate details) or a valid empty state, and typing in 'Search jobs...' narrows the visible cards to matches OR shows a 'No jobs found' message, with clearing the search restoring the set"
      ]
    },
    {
      "name": "jobs-status-filter",
      "instruction": "filter popover Status narrows the grid",
      "visualCriteria": [
        "The filter popover opens showing Status and Type dropdown fields, and selecting a Status narrows the card grid to matches OR shows a no-results empty state with an active-filter count/indicator appearing"
      ]
    },
    {
      "name": "create-job-slideout",
      "instruction": "New Job slide-in editor with schedule fields",
      "visualCriteria": [
        "Clicking 'New Job' opens a slide-in editor panel showing the Schedule section with a Cron Expression field, a Timezone dropdown, and a Concurrency dropdown (plus Name/Job Type in the General section)"
      ]
    },
    {
      "name": "create-job-validation",
      "instruction": "Create button gated by required fields",
      "visualCriteria": [
        "With required fields (Name, Job Type, Cron Expression, each marked with an asterisk) blank the 'Create' button is disabled, and it becomes enabled once Name, Job Type and Cron Expression are all filled"
      ]
    },
    {
      "name": "edit-job-slideout",
      "instruction": "Edit-mode editor pre-filled with Save+Delete",
      "visualCriteria": [
        "Clicking a job card opens the slide-in editor pre-filled with that job's values in edit mode, its footer showing both Save and Delete (and a Statistics section if the job has run history) — OR, if no jobs exist, a valid empty-state is shown"
      ]
    },
    {
      "name": "pause-resume-toggle",
      "instruction": "Pause/Resume flips job status chip",
      "visualCriteria": [
        "Clicking a job card's Pause/Resume button flips that job's status chip (Active<->Paused) and relabels the button accordingly — OR a valid empty-state is shown if no jobs exist"
      ]
    },
    {
      "name": "delete-confirmation",
      "instruction": "inline delete confirmation gate + Cancel",
      "visualCriteria": [
        "Clicking a card's Delete button shows an inline 'Delete this scheduled job?' confirmation with Delete and Cancel options, and clicking Cancel dismisses it with the job card still present (no deletion) — OR a valid empty-state if no jobs exist"
      ]
    }
  ]
}
